CREATE TABLE IF NOT EXISTS migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS memberships (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('owner','editor','viewer')), PRIMARY KEY(user_id,profile_id));
CREATE TABLE IF NOT EXISTS series (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, title TEXT NOT NULL, bible TEXT NOT NULL DEFAULT '', UNIQUE(id,profile_id));
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, series_id TEXT, title TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'short' CHECK(kind IN ('short','episode','feature')), logline TEXT NOT NULL DEFAULT '', story TEXT NOT NULL DEFAULT '', style TEXT NOT NULL DEFAULT '', fps INTEGER NOT NULL DEFAULT 24 CHECK(fps IN (24,25,30)), width INTEGER NOT NULL DEFAULT 1920, height INTEGER NOT NULL DEFAULT 1080, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(series_id,profile_id) REFERENCES series(id,profile_id), UNIQUE(id,profile_id));
CREATE TABLE IF NOT EXISTS scenes (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, heading TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', screenplay TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL, UNIQUE(id,project_id));
CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, filename TEXT NOT NULL, stored_name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, local_path TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(id,profile_id));
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('character','location','prop','costume','style','voice')), description TEXT NOT NULL DEFAULT '', prompt TEXT NOT NULL DEFAULT '', continuity TEXT NOT NULL DEFAULT '', media_id TEXT, FOREIGN KEY(media_id,profile_id) REFERENCES media(id,profile_id), UNIQUE(id,profile_id));
CREATE TABLE IF NOT EXISTS shots (id TEXT PRIMARY KEY, scene_id TEXT NOT NULL REFERENCES scenes(id) ON DELETE CASCADE, title TEXT NOT NULL, action TEXT NOT NULL DEFAULT '', dialogue TEXT NOT NULL DEFAULT '', camera TEXT NOT NULL DEFAULT '', prompt TEXT NOT NULL DEFAULT '', negative_prompt TEXT NOT NULL DEFAULT '', continuity TEXT NOT NULL DEFAULT '', duration REAL NOT NULL DEFAULT 5 CHECK(duration>0 AND duration<=600), position INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','storyboard','production','review','approved')), storyboard_id TEXT REFERENCES media(id) ON DELETE SET NULL, end_frame_id TEXT REFERENCES media(id) ON DELETE SET NULL, selected_take_id TEXT REFERENCES takes(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS asset_attachments (id TEXT PRIMARY KEY, asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE CASCADE, media_id TEXT NOT NULL REFERENCES media(id), label TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shot_assets (shot_id TEXT NOT NULL REFERENCES shots(id) ON DELETE CASCADE, asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE CASCADE, PRIMARY KEY(shot_id,asset_id));
CREATE TABLE IF NOT EXISTS takes (id TEXT PRIMARY KEY, shot_id TEXT NOT NULL REFERENCES shots(id) ON DELETE CASCADE, media_id TEXT NOT NULL REFERENCES media(id), label TEXT NOT NULL, provider TEXT NOT NULL DEFAULT 'manual', model TEXT NOT NULL DEFAULT '', prompt TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', cost REAL NOT NULL DEFAULT 0 CHECK(cost>=0), trim_in REAL NOT NULL DEFAULT 0 CHECK(trim_in>=0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audio_cues (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, media_id TEXT NOT NULL REFERENCES media(id), label TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('dialogue','music','sfx','ambience')), offset REAL NOT NULL DEFAULT 0 CHECK(offset>=0), trim_in REAL NOT NULL DEFAULT 0 CHECK(trim_in>=0), duration REAL NOT NULL DEFAULT 5 CHECK(duration>0), volume REAL NOT NULL DEFAULT 1 CHECK(volume>=0 AND volume<=4));
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, shot_id TEXT REFERENCES shots(id) ON DELETE CASCADE, project_id TEXT REFERENCES projects(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('image','video','roughcut')), provider TEXT NOT NULL, model TEXT NOT NULL DEFAULT '', prompt TEXT NOT NULL DEFAULT '', input_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','succeeded','failed','cancelled')), error TEXT NOT NULL DEFAULT '', output_media_id TEXT REFERENCES media(id), cost REAL NOT NULL DEFAULT 0 CHECK(cost>=0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS projects_profile ON projects(profile_id);
CREATE INDEX IF NOT EXISTS assets_profile ON assets(profile_id);
CREATE INDEX IF NOT EXISTS asset_attachments_order ON asset_attachments(asset_id,position,id);
CREATE INDEX IF NOT EXISTS scenes_order ON scenes(project_id,position);
CREATE INDEX IF NOT EXISTS shots_order ON shots(scene_id,position);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(status,created_at);
